<?php
/*
Plugin Name: Gallery Plugin
Plugin URI: https://www.example.com/gallery-plugin
Description: A plugin that adds a custom post type for galleries.
Version: 1.0
Author: Your Name
Author URI: https://www.example.com
*/

// Add custom post type for galleries
function add_gallery_post_type() {
    register_post_type( 'gallery',
        array(
            'labels' => array(
                'name' => __( 'Gallery' ),
                'singular_name' => __( 'Gallery' )
            ),
            'public' => true,
            'has_archive' => true,
            'menu_icon' => 'dashicons-image',
            'supports' => array( 'title', 'editor', 'comments', 'thumbnail' ),
        )
    );
}
add_action( 'init', 'add_gallery_post_type' );

// Add default gallery post
function add_default_gallery_post() {
    $gallery = array(
        'post_type' => 'gallery',
        'post_title' => 'Default Gallery',
        'post_content' => '',
        'post_status' => 'publish',
        'thumbnail' => get_stylesheet_directory() . '/images/gallery.jpg',
    );
    wp_insert_post( $gallery );
}
add_action( 'admin_menu', 'add_default_gallery_post' );
```
